import React, { useEffect, useState } from "react";
import ArrowDropDownIcon from "@mui/icons-material/ArrowDropDown";
import OpenInNewIcon from "@mui/icons-material/OpenInNew";
import { useNavigate } from "react-router-dom";
import OrderImage from "../../assets/orders/order1.png";
import { apisPath, paths } from "../../utils/path";
import http from "../../services/utility";

export default function Orders() {
  const navigate = useNavigate();
  const [orderFilter, setOrderFilter] = useState(0);

  const [productTableData, setProductTableData] = useState([]);
  const [completedTableData, setCompletedTableData] = useState([]);

  useEffect(() => {
    getData();
  }, []);

  const getData = async () => {
    await http
      .get(apisPath?.admin?.orders)
      .then(async (res) => {
        var activeData = res?.data?.active;
        var completedData = res?.data?.completed;
        setProductTableData(activeData);
        setCompletedTableData(completedData);
      })
      .catch((err) => {
        console.log(err);
      });
  };

  const handleOrderFilter = (val) => {
    setOrderFilter(val);
  };

  return (
    <div className="orders">
      <h3 className="orders__heading page_heading">Orders</h3>
      <div className="orders__content">
        <div className="orders__content__filter_header">
          <span
            className={`${orderFilter === 0 ? "active gradient-red-text" : ""}`}
            onClick={() => handleOrderFilter(0)}
          >
            Active Order
          </span>
          <span
            className={`${orderFilter === 1 ? "active gradient-red-text" : ""}`}
            onClick={() => handleOrderFilter(1)}
          >
            Completed Order
          </span>
        </div>
        {orderFilter === 0 ? (
          <ActiveOrders navigate={navigate} tableData={productTableData} />
        ) : (
          <CompletedOrders navigate={navigate} tableData={completedTableData} />
        )}
      </div>
    </div>
  );
}

const ActiveOrders = ({ navigate, tableData }) => {
  const [tableHeader, setTableHeader] = useState([
    { name: "Order ID" },
    { name: "Customer Name" },
    { name: "Product" },
    { name: "Date" },
    { name: "Price" },
    { name: "Status" },
  ]);

  return (
    <div className="orders__content__filter_content">
      <table className="orders__content__filter_content__table">
        <tr>
          {tableHeader?.map((header, index) => {
            return (
              <th key={index}>
                <span>
                  {header?.name} <ArrowDropDownIcon />
                </span>
              </th>
            );
          })}
        </tr>
        {tableData?.map((data, index) => {
          return (
            <tr key={index}>
              <td>{data?.orderID}</td>
              <td>
                {!data?.user?.name || data?.user?.name === ""
                  ? "Unknown"
                  : data?.user?.name}
              </td>
              <td>
                <div className="product">
                  <img src={data?.product[0]?.images[0]} alt="Product Image" />
                  <div className="product__info">
                    <span>{data?.product[0]?.name}</span>
                    <span>
                      <b>Details:</b>{" "}
                      {data?.product[0]?.details[0]?.body?.length > 140
                        ? data?.product[0]?.details[0]?.body?.substring(
                            0,
                            140
                          ) + "..."
                        : data?.product[0]?.details[0]?.body}
                    </span>
                  </div>
                </div>
              </td>
              <td>{data?.createdAt?.split("T")[0]}</td>
              <td>&#8377; {data?.amount}</td>
              <td>
                <div>
                  {/* {data?.status === "PP" && "Pending Pickup"}
                  {data?.status === "IT" && "In Transit"}
                  {data?.status === "EX" && "Exception"}
                  {data?.status === "FD" && "Out For Delivery"}
                  {data?.status === "DL" && "Delivered"}
                  {data?.status === "RT" && "RTO"}
                  {data?.status === "RT-IT" && "RTO In Transit"}
                  {data?.status === "RT-DL" && "RTO Delivered"} */}
                  {data?.status}
                  <OpenInNewIcon
                    sx={{
                      fontSize: 18,
                      color: "red",
                      cursor: "pointer",
                    }}
                    onClick={() =>
                      navigate(`/${paths?.front?.user?.orders}/${index}`, {
                        state: { data: data },
                      })
                    }
                  />
                </div>
              </td>
            </tr>
          );
        })}
      </table>
    </div>
  );
};

